       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");

       const fields = [
         {
           input: document.getElementById("full-name"),
           error: document.getElementById("full-name-error"),
           validate(value) {
             if (!value.trim()) {
               return "Enter your full name.";
             }
             return "";
           },
         },
         {
           input: document.getElementById("email-address"),
           error: document.getElementById("email-address-error"),
           validate(value, input) {
             if (!value.trim()) {
               return "Enter your email address.";
             }
             if (input.validity.typeMismatch) {
               return "Enter an email address in a valid format.";
             }
             return "";
           },
         },
         {
           input: document.getElementById("phone-number"),
           error: document.getElementById("phone-number-error"),
           validate(value) {
             const trimmed = value.trim();
             if (!trimmed) {
               return "";
             }
             const phonePattern = /^[+]?[0-9()\-\s]{7,20}$/;
             if (!phonePattern.test(trimmed)) {
               return "Use digits and common separators only, such as (555) 123-4567.";
             }
             return "";
           },
         },
       ];

       function setFieldState(field, message) {
         const hasError = Boolean(message);
         field.input.setAttribute("aria-invalid", hasError ? "true" : "false");
         field.error.textContent = message;
         field.error.hidden = !hasError;
         return hasError;
       }

       function validateField(field) {
         return setFieldState(field, field.validate(field.input.value, field.input));
       }

       fields.forEach((field) => {
         field.input.addEventListener("blur", () => {
           validateField(field);
         });

         field.input.addEventListener("input", () => {
           if (!field.error.hidden) {
             validateField(field);
           } else if (field.input.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         let firstInvalidField = null;

         fields.forEach((field) => {
           const hasError = validateField(field);
           if (hasError && !firstInvalidField) {
             firstInvalidField = field.input;
           }
         });

         if (firstInvalidField) {
           status.textContent = "Please correct the highlighted fields and try again.";
           firstInvalidField.focus();
           return;
         }

         status.textContent = "Your message is ready to send.";
         form.reset();
         fields.forEach((field) => setFieldState(field, ""));
       });
     </script>
   </body>
 </html>

